style.css:
@-moz-document domain("www.turkhackteam.org") {
/* --- GENEL SAYFA YAPISI --- */
    .p-pageWrapper {
        position: relative;
        display: flex;
        flex-direction: column;
        min-height: 100vh;
        background: #0A0A0A !important;
    }

    .block-tabHeader {
    padding: 0;
    margin: 0;
    font-size: 14px;
    color: red !important;
    background: #0A0A0A;
    border-bottom: 1px solid #232323;
    font-weight: bold;
}

    .xgtForumIstatistik .xgtForumIstatistik-tabHeader.block-tabHeader {
        background: #636363 !important;
        color: #0A0A0A !important;
        border-bottom: none;
    }

    .p-nav {
        color: #ffffff !important;
        background: #0A0A0A !important;
    }

    .block-container {
        color: #bfbfbf;
        background: #0A0A0A !important;
        border-width: 1px;
        border-style: solid;
        border-top-color: #232323;
        border-right-color: #232323;
        border-bottom-color: #161616;
        border-left-color: #232323;
        border-radius: 3px;
    }

    .p-body-sidebar .block .block-minorHeader, .p-body-sideNavContent .block .block-minorHeader {
    font-size: 16px;
    color: red;
    font-weight: 600;
    background: #0A0A0A !important;
    border-bottom: 2px solid #232323;
}

    .block-container {
        color: #bfbfbf;
        background: #0A0A0A !important;
        border-width: 1px;
        border-style: solid;
        border-top-color: #232323;
        border-right-color: #232323;
        border-bottom-color: #161616;
        border-left-color: #232323;
        border-radius: 3px;
    }

    html {
        font-family: 'Verdana', 'Helvetica Neue', Helvetica, Roboto, Oxygen, Ubuntu, Cantarell, 'Fira Sans', 'Droid Sans', sans-serif;
    }

    .p-header-content {
        padding: 12px 0;
        display: flex;
        flex-wrap: wrap;
        justify-content: space-between;
